class Solution { fun findBestValue(arr:IntArray,target:Int):Int{var left=0;var right=arr.max();fun sum(cap:Int):Long{return arr.sumOf{minOf(it,cap).toLong()}};while(left<right){val middle=(left+right)/2;if(sum(middle)>=target)right=middle else left=middle+1};val lower=maxOf(0,left-1);return if(kotlin.math.abs(sum(lower)-target)<=kotlin.math.abs(sum(left)-target))lower else left} }
